class Solution:
    def minimizeTheDifference(self, mat: List[List[int]], target: int) -> int:
        possible = {0}
        for row in mat:
            new_possible = set()
            for s in possible:
                for val in row:
                    new_possible.add(s + val)
            # 剪枝：只保留<=target的全部，以及>target的最小值
            min_above = float('inf')
            pruned = set()
            for s in new_possible:
                if s <= target:
                    pruned.add(s)
                else:
                    min_above = min(min_above, s)
            if min_above != float('inf'):
                pruned.add(min_above)
            possible = pruned
        return min(abs(s - target) for s in possible)

class Solution:
    def recoverArray(self, n: int, sums: List[int]) -> List[int]:
        from collections import Counter
        sums.sort()
        res = []
        while len(sums) > 1:
            x = sums[1] - sums[0]  # candidate element
            cnt = Counter(sums)
            with_x, without_x = [], []
            zero_in_without = False
            for s in sums:
                if cnt[s] > 0:
                    cnt[s] -= 1
                    without_x.append(s)
                    if s == 0:
                        zero_in_without = True
                    cnt[s + x] -= 1
                    with_x.append(s + x)
            if zero_in_without:
                res.append(x)
                sums = without_x
            else:
                res.append(-x)
                sums = with_x
        return res

