class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        dp = [(float('inf'), 0)] * (1 << n)
        dp[0] = (1, 0)
        for mask in range(1, 1 << n):
            for i in range(n):
                if mask & (1 << i):
                    prev = mask ^ (1 << i)
                    sessions, used = dp[prev]
                    if used + tasks[i] <= sessionTime:
                        candidate = (sessions, used + tasks[i])
                    else:
                        candidate = (sessions + 1, tasks[i])
                    dp[mask] = min(dp[mask], candidate)
        return dp[(1 << n) - 1][0]

