class DetectSquares:
    def __init__(self):
        from collections import Counter
        self.cnt = Counter()
        self.points = []

    def add(self, point: List[int]) -> None:
        self.cnt[tuple(point)] += 1
        self.points.append(point)

    def count(self, point: List[int]) -> int:
        x1, y1 = point
        res = 0
        for x2, y2 in self.points:
