        return res

class Solution:
    def longestSubsequenceRepeatedK(self, s: str, k: int) -> str:
        from collections import Counter
        cnt = Counter(s)
        chars = sorted([c for c in cnt if cnt[c] >= k], reverse=True)

        def is_subseq(sub, s, k):
            # check if sub repeated k times is a subsequence of s
            idx = 0
            for _ in range(k):
                for c in sub:
                    idx = s.find(c, idx)
                    if idx == -1: return False
                    idx += 1
            return True

        from collections import deque
        q = deque([''])
        res = ''
        while q:
            cur = q.popleft()
            for c in chars:
                nxt = cur + c
                if is_subseq(nxt, s, k):
                    if len(nxt) > len(res) or (len(nxt) == len(res) and nxt > res):
                        res = nxt
                    q.append(nxt)
        return res

