class Solution:
    def missingRolls(self, rolls: List[int], mean: int, n: int) -> List[int]:
        total = mean * (len(rolls) + n)
        need = total - sum(rolls)
        if need < n or need > 6 * n:
            return []
        base, extra = divmod(need, n)
        return [base + 1] * extra + [base] * (n - extra)

