class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, repetition: int) -> str:
        n = len(s)
        # suffix count of letter
        letter_cnt = s.count(letter)
        stack = []
        letter_in_stack = 0
        for i, c in enumerate(s):
            while stack and stack[-1] > c and len(stack) + (n - i) > k:
                if stack[-1] == letter:
                    if letter_cnt + letter_in_stack - 1 < repetition:
                        break
                    letter_in_stack -= 1
                stack.pop()
            if len(stack) < k:
                stack.append(c)
                if c == letter:
                    letter_in_stack += 1
            if c == letter:
                letter_cnt -= 1
        # ensure repetition: replace from end
        res = list(stack)
        need = repetition - letter_in_stack
        for i in range(k - 1, -1, -1):
            if need <= 0:
                break
            if res[i] != letter:
                res[i] = letter
                need -= 1
        return ''.join(res)

