class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        from bisect import bisect_left
        n = len(nums) // 2
        total = sum(nums)
        left, right = nums[:n], nums[n:]
        # generate all subset sums grouped by size
        def get_sums(arr):
            m = len(arr)
            sums = [[] for _ in range(m + 1)]
            for mask in range(1 << m):
                s = sum(arr[i] for i in range(m) if mask & (1 << i))
                sums[bin(mask).count('1')].append(s)
            return sums
        left_sums = get_sums(left)
        right_sums = get_sums(right)
        for s in right_sums:
            s.sort()
        res = float('inf')
        for k in range(n + 1):
            for ls in left_sums[k]:
                target = total / 2 - ls
                rs = right_sums[n - k]
                idx = bisect_left(rs, target)
                for i in [idx - 1, idx]:
                    if 0 <= i < len(rs):
                        s1 = ls + rs[i]
                        res = min(res, abs(total - 2 * s1))
        return res

