                if a > 0:
                    # a*b <= mid => b <= mid/a (pos2), -b >= -mid/a (neg2 as positive)
                    cnt += bisect_right(pos2, mid / a)
                    cnt += len(neg2) - bisect_left(neg2, -mid / a)
                    cnt += len(zero2) if mid >= 0 else 0
                elif a < 0:
                    # a*b <= mid => b >= mid/a (since a<0, division flips)
                    cnt += len(pos2) - bisect_left(pos2, mid / a)
                    cnt += bisect_right(neg2, -mid / a)
                    cnt += len(zero2) if mid >= 0 else 0
                else:
                    cnt += len(nums2) if mid >= 0 else 0
            return cnt

        lo, hi = -10**10, 10**10
        while lo < hi:
            mid = (lo + hi) // 2
            if count_le(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo
